%% -- Private helpers --

to_binary(V) when is_binary(V) -> V;
to_binary(V) when is_list(V) -> list_to_binary(V);
to_binary(V) when is_integer(V) -> integer_to_binary(V);
to_binary(V) when is_float(V) -> float_to_binary(V);
to_binary(true) -> <<"true">>;
to_binary(false) -> <<"false">>;
to_binary(V) when is_atom(V) -> atom_to_binary(V, utf8).

encode_query_value(V) when is_boolean(V) ->
    atom_to_binary(V, utf8);
encode_query_value(V) when is_integer(V) ->
    integer_to_binary(V);
encode_query_value(V) when is_float(V) ->
    float_to_binary(V);
encode_query_value(V) when is_binary(V) ->
    V;
encode_query_value(V) when is_atom(V) ->
    atom_to_binary(V, utf8).

uri_encode(Value) ->
    uri_string:quote(Value).

prefix_headers_to_list(_Prefix, undefined) ->
    [];
prefix_headers_to_list(Prefix, Map) when is_map(Map) ->
    [{<<Prefix/binary, H/binary>>, to_binary(V)} || {H, V} <- maps:to_list(Map)].

header_value(Headers, Name) ->
    case proplists:get_value(Name, Headers, undefined) of
        undefined ->
            Lower = list_to_binary(string:lowercase(binary_to_list(Name))),
            proplists:get_value(Lower, Headers, undefined);
        Value ->
            Value
    end.

prefix_headers_from_list(Headers, Prefix) ->
    Map = maps:from_list([
        {binary:part(Name, byte_size(Prefix), byte_size(Name) - byte_size(Prefix)), Val}
        || {Name, Val} <- Headers,
           byte_size(Name) > byte_size(Prefix),
           binary:part(Name, 0, byte_size(Prefix)) =:= Prefix
    ]),
    case maps:size(Map) of
        0 -> undefined;
        _ -> Map
    end.
